import React, { useEffect, useState } from 'react';
import api from '../../api/axios';
import { Container, Table, Button } from 'react-bootstrap';

const Students = () => {
  const [students, setStudents] = useState([]);

  useEffect(() => {
    const fetchStudents = async () => {
      const res = await api.get('/director/students');
      setStudents(res.data);
    };
    fetchStudents();
  }, []);

  const handleDelete = async (id) => {
    if (window.confirm('Удалить ученика?')) {
      await api.delete(`/director/student/${id}`);
      setStudents(students.filter(s => s.id !== id));
    }
  };

  return (
    <Container className="mt-4">
      <h3>Ученики (для директора)</h3>
      <Table striped bordered hover>
        <thead>
          <tr><th>ФИО</th><th>Класс</th><th>Email</th><th>Средняя оценка</th><th>Действия</th></tr>
        </thead>
        <tbody>
          {students.map(s => (
            <tr key={s.id}>
              <td>{s.last_name} {s.first_name}</td>
              <td>{s.class}</td>
              <td>{s.email}</td>
              <td>{s.average_grade}</td>
              <td><Button variant="danger" onClick={() => handleDelete(s.id)}>Удалить</Button></td>
            </tr>
          ))}
        </tbody>
      </Table>
    </Container>
  );
};

export default Students;
